function solve(adj, start) {
  const n = adj.length;
  const rows = [];
  for (let i = 0; i < n; i++) rows.push(Array.isArray(adj[i]) ? adj[i] : []);
  if (start < 0 || start >= n) return [];
  const reachable = new Array(n).fill(false);
  reachable[start] = true;
  let changed = true;
  while (changed) {
    changed = false;
    for (let u = 0; u < n; u++) {
      if (!reachable[u]) continue;
      for (const v of rows[u]) {
        if (v < 0 || v >= n) continue;
        if (!reachable[v]) { reachable[v] = true; changed = true; }
      }
    }
  }
  const seen = new Set();
  const edges = [];
  for (let u = 0; u < n; u++) {
    if (!reachable[u]) continue;
    for (const v of rows[u]) {
      if (v < 0 || v >= n || !reachable[v]) continue;
      const key = Math.min(u, v) + ',' + Math.max(u, v);
      if (!seen.has(key)) { seen.add(key); edges.push([Math.min(u, v), Math.max(u, v)]); }
    }
  }
  edges.sort((x, y) => (x[0] - y[0]) || (x[1] - y[1]));
  return edges;
}

